def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    max_sum = 0
    prev_max = -float('inf')

    for i in range(1, n):
        curr = arr[i]
        prev = arr[i - 1]

        # If current is greater than previous, update max_sum
        if curr > prev:
            max_sum = max(max_sum, curr)
            prev_max = curr

        # If current is less than or equal to previous, check if it's a valid bitonic sequence
        # A bitonic sequence must be strictly increasing then strictly decreasing
        # So if prev_max is not -inf, we can't form a valid bitonic sequence ending here
        if prev_max != -float('inf'):
            if curr <= prev_max:
                max_sum = max(max_sum, curr)
                prev_max = curr

    return max_sum

