def max_subarray_product(arr):
    max_val = 1
    current_max = 1
    if arr:
        current_max = arr[0]
        max_val = current_max
    for x in arr[1:]:
        if x > 0:
            current_max *= x
            max_val = max(max_val, current_max)
        else:
            current_max = 0
            max_val = 0
    return max_val if max_val != 0 else 0

